import React, { useState, useContext } from "react";
import { GlobalContext } from "../context/GlobalState";
import styled, { keyframes, css } from "styled-components";

// Neon glow animation
const neonGlow = keyframes`
  0%, 100% {
    text-shadow: 0 0 5px #fff, 0 0 10px #fff, 0 0 15px #0073e6, 0 0 20px #0073e6;
  }
  50% {
    text-shadow: 0 0 10px #fff, 0 0 20px #fff, 0 0 30px #0073e6, 0 0 40px #0073e6;
  }
`;

// Floating hologram effect
const hologramFloat = keyframes`
  0% {
    transform: translateY(0) rotateX(0deg);
    box-shadow: 0 25px 40px rgba(0, 115, 230, 0.2);
  }
  50% {
    transform: translateY(-10px) rotateX(5deg);
    box-shadow: 0 35px 60px rgba(0, 115, 230, 0.4);
  }
  100% {
    transform: translateY(0) rotateX(0deg);
    box-shadow: 0 25px 40px rgba(0, 115, 230, 0.2);
  }
`;

// Particle animation
const particles = keyframes`
  0% {
    background-position: 0% 50%;
  }
  100% {
    background-position: 100% 50%;
  }
`;

// Cyberpunk theme colors
const cyberTheme = {
  primary: "#00f0ff",
  secondary: "#ff00f0",
  accent: "#00ffa3",
  dark: "#0a0a20",
  light: "#e0e0ff",
  glow: "#0073e6",
  matrix: "#00ff41",
};

// Holographic container with particle effect
const CyberContainer = styled.div`
  background: linear-gradient(135deg, rgba(10, 10, 32, 0.9), rgba(20, 20, 60, 0.95));
  border-radius: 16px;
  padding: 2.5rem;
  margin: 2rem 0;
  border: 1px solid rgba(0, 240, 255, 0.3);
  box-shadow: 0 0 30px rgba(0, 240, 255, 0.1), 
              inset 0 0 20px rgba(0, 240, 255, 0.1);
  position: relative;
  overflow: hidden;
  animation: ${hologramFloat} 8s ease-in-out infinite;
  transform-style: preserve-3d;
  perspective: 1000px;
  backdrop-filter: blur(5px);
  z-index: 1;

  &::before {
    content: "";
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: linear-gradient(
      to right,
      transparent,
      rgba(0, 240, 255, 0.1),
      transparent
    );
    transform: rotate(45deg);
    animation: ${particles} 15s linear infinite;
    z-index: -1;
  }

  &:hover {
    animation: ${hologramFloat} 4s ease-in-out infinite;
    box-shadow: 0 0 40px rgba(0, 240, 255, 0.2), 
                inset 0 0 30px rgba(0, 240, 255, 0.2);
  }
`;

// Cyberpunk title with neon effect
const CyberTitle = styled.h3`
  color: ${cyberTheme.primary};
  font-size: 1.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 2rem;
  text-align: center;
  position: relative;
  animation: ${neonGlow} 1.5s ease-in-out infinite alternate;
  text-shadow: 0 0 5px #fff, 0 0 10px #fff, 0 0 15px ${cyberTheme.glow};

  &::after {
    content: "";
    position: absolute;
    bottom: -10px;
    left: 50%;
    transform: translateX(-50%);
    width: 100px;
    height: 3px;
    background: linear-gradient(90deg, transparent, ${cyberTheme.accent}, transparent);
    box-shadow: 0 0 10px ${cyberTheme.accent};
  }
`;

// Cyber form with grid layout
const CyberForm = styled.form`
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.8rem;
  transform-style: preserve-3d;
`;

// Cyber input with data-matrix effect
const CyberInput = styled.input`
  padding: 1.2rem 1.5rem;
  background: rgba(10, 10, 32, 0.7);
  border: 1px solid ${cyberTheme.primary};
  border-radius: 8px;
  font-size: 1.1rem;
  color: ${cyberTheme.light};
  transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
  outline: none;
  box-shadow: 0 0 10px rgba(0, 240, 255, 0.1);
  position: relative;
  z-index: 1;
  font-family: 'Courier New', monospace;

  &::placeholder {
    color: rgba(224, 224, 255, 0.5);
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  &:focus {
    background: rgba(20, 20, 60, 0.9);
    border-color: ${cyberTheme.accent};
    box-shadow: 0 0 20px ${cyberTheme.accent};
    transform: translateY(-3px);

    &::placeholder {
      color: transparent;
    }
  }

  /* Data matrix effect when focused */
  &:focus::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: 
      linear-gradient(90deg, rgba(0, 255, 65, 0.1) 1px, transparent 1px),
      linear-gradient(rgba(0, 255, 65, 0.1) 1px, transparent 1px);
    background-size: 10px 10px;
    border-radius: 8px;
    z-index: -1;
    animation: ${particles} 20s linear infinite;
  }
`;

// Cyber button with loading effect
const CyberButton = styled.button`
  background: linear-gradient(135deg, ${cyberTheme.primary}, ${cyberTheme.secondary});
  color: ${cyberTheme.dark};
  border: none;
  padding: 1.2rem;
  border-radius: 8px;
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
  position: relative;
  overflow: hidden;
  z-index: 1;
  box-shadow: 0 0 15px rgba(0, 240, 255, 0.5);
  border: 1px solid rgba(0, 240, 255, 0.7);

  &:hover {
    transform: translateY(-3px) scale(1.02);
    box-shadow: 0 0 25px rgba(0, 240, 255, 0.8);
    background: linear-gradient(135deg, ${cyberTheme.secondary}, ${cyberTheme.primary});
  }

  &:active {
    transform: translateY(1px);
  }

  &:disabled {
    background: #333;
    color: #666;
    cursor: not-allowed;
    box-shadow: none;
    border-color: #444;
  }

  /* Scanning line effect */
  &::before {
    content: "";
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(
      90deg,
      transparent,
      rgba(255, 255, 255, 0.2),
      transparent
    );
    transition: none;
  }

  &:hover::before {
    left: 100%;
    transition: all 0.8s ease-in-out;
  }
`;

// Status indicator
const StatusIndicator = styled.div`
  display: flex;
  justify-content: space-between;
  margin-top: 1rem;

  span {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: ${({ $status }) => 
      $status === 'ready' ? cyberTheme.accent : 
      $status === 'error' ? '#ff0033' : '#666'};
    box-shadow: 0 0 5px ${({ $status }) => 
      $status === 'ready' ? cyberTheme.accent : 
      $status === 'error' ? '#ff0033' : 'transparent'};
    transition: all 0.3s ease;
  }
`;

const AddTransaction = () => {
  const { addTransaction } = useContext(GlobalContext);
  const [text, setText] = useState("");
  const [amount, setAmount] = useState("");
  const [status, setStatus] = useState("idle");

  const onSubmit = (e) => {
    e.preventDefault();

    if (!text || !amount) {
      setStatus("error");
      setTimeout(() => setStatus("idle"), 2000);
      return;
    }

    setStatus("processing");
    
    setTimeout(() => {
      const newTransaction = {
        id: Math.floor(Math.random() * 100000),
        text,
        amount: +amount,
      };

      addTransaction(newTransaction);
      setText("");
      setAmount("");
      setStatus("complete");
      
      setTimeout(() => setStatus("idle"), 1500);
    }, 800);
  };

  return (
    <CyberContainer>
      <CyberTitle>Transaction Terminal</CyberTitle>
      <CyberForm onSubmit={onSubmit}>
        <CyberInput
          type="text"
          placeholder="DESCRIPTION"
          value={text}
          onChange={(e) => setText(e.target.value)}
        />
        <CyberInput
          type="number"
          placeholder="AMOUNT (CREDIT/DEBIT)"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
        <CyberButton 
          type="submit" 
          disabled={!text || !amount || status === "processing"}
        >
          {status === "processing" ? "Processing..." : "Execute Transaction"}
        </CyberButton>
        <StatusIndicator $status={
          !text || !amount ? "error" : 
          status === "processing" ? "processing" : 
          status === "complete" ? "ready" : "idle"
        }>
          {[...Array(5)].map((_, i) => <span key={i} />)}
        </StatusIndicator>
      </CyberForm>
    </CyberContainer>
  );
};

export default AddTransaction;
